preConditionHook:
// The breakout bar is bar 1, so the level it broke is the extreme of the
// breakoutLookback bars ending one bar before IT: EL lowest(low, n)[2], bars
// 2..breakoutLookback + 1. A history reference at a CONSTANT offset, so the
// built-in stands in the EL twin; here it is the Extremes() loop that built-in
// bottoms out in -- seeded at the window's first bar, scanned strictly with
// the tolerance-carrying comparison (see Breakout).
//
// Read into locals so exactly one evaluation per bar feeds both conditions.
lvlLow = low[2];
lvlHigh = high[2];
for (int i = 3; i <= (int)breakoutLookback + 1; ++i) {
    if (el_lt(low[i], lvlLow)) lvlLow = low[i];
    if (el_gt(high[i], lvlHigh)) lvlHigh = high[i];
}
